import { ethers } from "ethers";
import { CONTRACTS, NATIVE_TOKEN, RPC_URL, MAX_UINT256 } from "./addresses";
import { PECOR_ABI, PECOR_ORDERS_ABI, PECOR_STOP_ORDERS_ABI, PECOR_QUOTER_ABI, PECOR_VAULT_ABI, PRICE_ORACLE_ABI, ERC20_ABI } from "./abis";
import type { QuoteResult, LimitOrder, StopLossOrder, StopLimitOrder, SwapParams } from "./types";

function deadline(seconds = 300): bigint {
    return seconds > 0 ? BigInt(Math.floor(Date.now() / 1000) + seconds) : 0n;
}

// ─── Approvals ────────────────────────────────────────────────────────────────

/**
 * Approve the PECORVault to spend a token.
 * Safe to call repeatedly — no-ops if already approved.
 */
export async function approveVault(
    tokenAddress: string,
    signer: ethers.Signer,
    amount: bigint = MAX_UINT256
): Promise<boolean> {
    const token = new ethers.Contract(tokenAddress, ERC20_ABI, signer);
    const owner = await signer.getAddress();
    const current = await token.allowance(owner, CONTRACTS.PECORVault) as bigint;
    if (current >= amount) return false;
    const tx = await token.approve(CONTRACTS.PECORVault, MAX_UINT256);
    await tx.wait();
    return true;
}

// ─── Quotes ───────────────────────────────────────────────────────────────────

export async function getQuote(
    tokenIn: string,
    tokenOut: string,
    amountIn: bigint,
    provider?: ethers.Provider
): Promise<QuoteResult> {
    const p = provider ?? new ethers.JsonRpcProvider(RPC_URL);
    const quoter = new ethers.Contract(CONTRACTS.PECORQuoter, PECOR_QUOTER_ABI, p);
    const actualIn = tokenIn === NATIVE_TOKEN.address ? NATIVE_TOKEN.wrappedAddress : tokenIn;
    const actualOut = tokenOut === NATIVE_TOKEN.address ? NATIVE_TOKEN.wrappedAddress : tokenOut;
    return quoter.quoteExactIn(actualIn, actualOut, amountIn) as Promise<QuoteResult>;
}

